\section{Introduction}

The problem of determining the minimal number of distinct eigenvalues of a graph $G$ has been studied in \cite{fiedler1975eigenvalues, ghorbani2013graphs, hogben2012zero, hogben2015minimum, liu2014note, zhang2016graphs}. This problem is closely related to the determination of the maximal nullity of $G$, i.e., the maximal dimension of the kernel of a matrix in the set of all real symmetric matrices whose nonzero pattern is given by the edges of $G$. The latter problem is well studied and has applications in chemistry, control theory, dynamical systems and combinatorics (see \cite{hogben2015minimum} for a survey). The minimal number of distinct eigenvalues of $G$, denoted by $q(G)$, is defined as the minimal number of distinct eigenvalues among all real symmetric matrices associated with $G$. For instance, $q(K_n)=2$ since the maximal multiplicity of an eigenvalue of a real symmetric matrix associated with $K_n$ is $n-1$ and the maximal multiplicity of a zero eigenvalue is $n-1$.

It was proved that $q(G) = 2$ if and only if $G$ is a complete graph or a complete bipartite graph (see \cite[Theorem 3.4]{hogben2015minimum}). Moreover, it was conjectured that $q(G) \leq 4$ for any connected graph $G$ different from $K_n$ and $K_{m,n}$ (see \cite[Conjecture 3.6]{hogben2015minimum}). This conjecture was recently disproved in \cite{wang2018graphs} where an infinite family of graphs $\mathcal{F}$ such that $q(G) \geq 5$ for any $G \in \mathcal{F}$ is constructed. However, it remains open whether $q(G) \leq 5$ for any connected graph $G$ different from $K_n$ and $K_{m,n}$.

In this paper we study the minimal number of distinct eigenvalues of a graph $G$ which is obtained by adding a pendant edge to another graph $H$, i.e., $G=H+K_{1}$. In other words, we determine $q(H+K_1)$ in terms of $q(H)$ and some other parameters of $H$. We also give a sharp upper bound on $q(H+K_1)$ in terms of $q(H)$ and characterize the extremal graphs. Finally, we provide an upper bound on $q(H+K_1)$ in terms of $q(H)$ and the diameter of $H$.

Let us briefly describe the organization of the paper. In Section \ref{sec:prelim} we recall some preliminary results and notations. In Section \ref{sec:main} we prove our main result, namely Theorem \ref{thm:main}. In Section \ref{sec:upperbound} we provide an upper bound on $q(H+K_1)$ in terms of $q(H)$ and characterize the extremal graphs. In Section \ref{sec:diameter} we provide an upper bound on $q(H+K_1)$ in terms of $q(H)$ and the diameter of $H$.

\section{Preliminaries}\label{sec:prelim}
Throughout this paper we assume that $G=(V,E)$ is a simple undirected graph on $n$ vertices. Let $A_G$ be the adjacency matrix of $G$ and let $D_G$ be the diagonal matrix of degrees of vertices of $G$. The Laplacian matrix of $G$ is defined as $L_G=D_G-A_G$.
We say that two graphs are cospectral if they have the same spectrum. If $S$ is a subset of $V(G)$, then the subgraph induced by $S$ is denoted by $G[S]$. The complement of $G$ is denoted by $\overline{G}$. A clique in a graph is a set of pairwise adjacent vertices. The maximum size of a clique in $G$ is called the clique number of $G$ and is denoted by $\omega(G)$. The independence number of $G$ is denoted by $\alpha(G)$. The distance between two vertices $u$ and $v$ in $G$ is the length of a shortest path connecting them and is denoted by $d(u,v)$. The eccentricity of a vertex $u$ in $G$ is the maximum distance from $u$ to any other vertex of $G$. The radius of $G$ is the minimum eccentricity of its vertices and the diameter of $G$ is the maximum eccentricity of its vertices. We denote the radius and the diameter of $G$ by $\mathrm{rad}(G)$ and $\mathrm{diam}(G)$, respectively. For more information on the above concepts, see \cite{west2001introduction}.
\begin{definition}
	Let $G$ be a graph on $n$ vertices. A real symmetric matrix $B$ is said to be associated with $G$ if $B_{ij} \neq 0$ if and only if $(i,j) \in E(G)$. The set of all real symmetric matrices associated with $G$ is denoted by $S(G)$. Let $M \in S(G)$ and let $A(M)$ be the adjacency matrix of $M$. We define
	$$
	\mathrm{null}(M):=\dim(\ker(M)) \quad \text{and} \quad q(G):=\min_{M \in S(G)}|\mathrm{spec}(M)|,
	$$
	where $\mathrm{spec}(M)$ denotes the spectrum of $M$.
\end{definition}

\begin{example}
	Let $G$ be a path on three vertices. Then $S(G)$ consists of the following matrices:
	\[
	\left(
	\begin{array}{ccc}
	0 & x & 0 \\
	x & y & z \\
	0 & z & 0 \\
	\end{array}
	\right),
	\]
	where $x,y,z \in \mathbb{R}$. It is easy to check that the minimal number of distinct eigenvalues of matrices in $S(G)$ is equal to $2$. Therefore $q(G)=2$.
\end{example}

\begin{definition}
	Let $G$ be a graph on $n$ vertices and let $M \in S(G)$. A vector $v \in \mathbb{R}^n$ is said to be a principal eigenvector of $M$ corresponding to an eigenvalue $\lambda$ if $v_i \neq 0$ for all $i \in [n]$ and $Mv=\lambda v$. A principal eigenvector of $M$ corresponding to an eigenvalue $\lambda$ is unique up to a scalar multiple.
\end{definition}

\begin{lemma}[{\cite[Lemma 2.3]{hogben2015minimum}}]\label{lem:principal}
	Let $G$ be a graph on $n$ vertices and let $M \in S(G)$. Then there exists a principal eigenvector corresponding to each eigenvalue of $M$.
\end{lemma}

\begin{definition}
	Let $G$ be a graph on $n$ vertices. A partition $\mathcal{P}=\{V_1,V_2,\dots,V_k\}$ of $V(G)$ is said to be equitable if for every pair of subsets $V_i,V_j \in \mathcal{P}$, the number of neighbors of any vertex in $V_i$ in $V_j$ is independent of the choice of the vertex in $V_i$.
\end{definition}

\begin{theorem}[{\cite[Theorem 2.2]{hogben2015minimum}}]\label{thm:equitable}
	Let $G$ be a graph on $n$ vertices and let $M \in S(G)$. Suppose that $\mathcal{P}=\{V_1,V_2,\dots,V_k\}$ is an equitable partition of $V(G)$. Let $M[\mathcal{P}]$ be the quotient matrix of $M$ with respect to $\mathcal{P}$, i.e.,
