    print(j)
else:
    print("J is no longer less than 10") # it will print when the loop ends

# break statement
for k in range(10):
    if k == 5:
        break
    print(k)

# continue statement
for l in range(10):
    if l % 2 == 0:
        continue
    print(l)

# pass statement
for m in range(10):
    if m == 5:
        pass
    print(m) # pass statement does nothing, it is used as a placeholder. It can be used when a statement is required syntactically but you do not want any command or code to execute.

