/**
 * Computes the greatest common divisor (GCD) of two numbers using the Euclidean algorithm.
 * 
 * The Euclidean algorithm is an efficient method for finding the GCD of two integers.
 * It repeatedly replaces the larger number by its remainder when divided by the smaller number,
 * until one of the numbers becomes zero. The non-zero number at this point is the GCD.
 * 
 * @param num1 - First positive integer
 * @param num2 - Second positive integer
 * @returns The greatest common divisor of num1 and num2
 */
function computeGCD(num1: number, num2: number): number {
    while (num2 !== 0) {
        let temp = num2;
        num2 = num1 % num2;
        num1 = temp;
    }
    return num1;
}

