class Solution:
    def countArrangement(self, N: int) -> int:
        nums = [i for i in range(1,N+1)]
        res = []
        def backtrack(nums, path):
            if not nums:
                res.append(path)
                return 
            for i in range(len(nums)):
                if nums[i] % len(path)+1 == 0 or len(path)+1 % nums[i] == 0:
                    backtrack(nums[:i]+nums[i+1:], path+[nums[i]])
        backtrack(nums, [])
        return len(res)

