def move(maze, pos, direction):
    if direction == up:
        return [pos[0]-1, pos[1]]
    elif direction == down:
        return [pos[0]+1, pos[1]]
    elif direction == left:
        return [pos[0], pos[1]-1]
    elif direction == right:
        return [pos[0], pos[1]+1]

def isValidMove(maze, pos):
    if pos[0] < 0 or pos[0] >= len(maze) or pos[1] < 0 or pos[1] >= len(maze[0]):
        return False
    if maze[pos[0]][pos[1]] == 1:
        return False
    return True

def isFinished(maze, pos):
    return pos[0] == len(maze)-1 and pos[1] == len(maze[0])-1

def solveMaze(maze, pos):
    if not isValidMove(maze, pos):
        return False

    if isFinished(maze, pos):
        maze[pos[0]][pos[1]] = 2
        return True

    maze[pos[0]][pos[1]] = 2

    if solveMaze(maze, move(maze, pos, up)):
        return True
    if solveMaze(maze, move(maze, pos, down)):
        return True
    if solveMaze(maze, move(maze, pos, left)):
        return True
    if solveMaze(maze, move(maze, pos, right)):
        return True

    maze[pos[0]][pos[1]] = 0
    return False


