import java.util.List;

public class Problem {

    /**
     * Given a list of integers, this method returns a new list where each element is the product of pairs of elements
     * from the original list. Pairs are formed by taking elements from the start and end of the list and moving towards
     * the center. If the list has an odd number of elements, the middle element is squared and added as the last element
     * of the result list.
     *
     * @param numbers A list of integers.
     * @return A list of integers where each element is the product of pair elements from the input list.
     */
    public static List<Integer> calculatePairProducts(List<Integer> numbers) {
        List<Integer> result = new ArrayList<>();
        int i = 0;
        int j = numbers.size() - 1;
        while (i <= j) {
            if (i == j) {
                result.add(numbers.get(i) * numbers.get(i));
            } else {
                result.add(numbers.get(i) * numbers.get(j));
            }
            i++;
            j--;
        }
        return result;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(calculatePairProducts(List.of(1, 2, 3, 4))); // Output: [4, 6]
        System.out.println(calculatePairProducts(List.of(1, 2, 3, 4, 5))); // Output: [5, 8, 9]
    }
}

