```cpp
#include <vector>

std::vector<std::vector<int>> createIdentityMatrix(int n) {
    std::vector<std::vector<int>> result(n, std::vector<int>(n));

    for (int i = 0; i < n; i++) {
        result[i][i] = 1;
    }

    return result;
}
