package com.github.nkzawa.socketio.android.client

import android.util.Log
import com.github.nkzawa.socketio.parser.Base64
import com.github.nkzawa.socketio.parser.Parser
import org.json.JSONObject
import java.io.BufferedReader
import java.io.IOException
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.net.HttpURLConnection
import java.net.URL
import java.nio.charset.StandardCharsets

internal class HttpPollingTransport(
    private val manager: Manager,
    private val uri: String,
    private val query: JSONObject?
) : Transport() {

    private var url: URL? = null
    private var httpConn: HttpURLConnection? = null
    private var parser: Parser? = null
    private var lastMessageId = 0L
    private var pendingMessages: MutableList<SocketIOClient.Message> = mutableListOf()

    override fun open() {
        if (isConnected()) return
        try {
            url = URL(uri)
            parser = manager.parserFactory.createParser()
            val message = SocketIOClient.Message(
                type = SocketIOClient.Message.Type.CONNECT,
                data = SocketIOClient.Message.Data(),
                id = ++lastMessageId
            )
            send(message)
        } catch (e: Exception) {
            Log.e(TAG, "open: $e")
            manager.onClose(e)
        }
    }

    override fun close() {
        if (!isConnected()) return
        try {
            val message = SocketIOClient.Message(
                type = SocketIOClient.Message.Type.DISCONNECT,
                data = SocketIOClient.Message.Data(),
                id = ++lastMessageId
            )
            send(message)
            parser?.close()
            parser = null
            httpConn?.disconnect()
            httpConn = null
            url = null
        } catch (e: Exception) {
            Log.e(TAG, "close: $e")
            manager.onClose(e)
        }
    }

    override fun ping() {
        if (!isConnected()) return
        try {
            val message = SocketIOClient.Message(
                type = SocketIOClient.Message.Type.PING,
                data = SocketIOClient.Message.Data(),
                id = ++lastMessageId
            )
            send(message)
        } catch (e: Exception) {
            Log.e(TAG, "ping: $e")
            manager.onClose(e)
        }
    }

    override fun send(message: SocketIOClient.Message) {
        if (!isConnected()) return
        try {
            val body = JSONObject()
            body.put("type", message.type.name.toLowerCase())
            body.put("data", message.data)
            if (message.id != -1L) body.put("id", message.id)
            val encodedBody = Base64.encode(body.toString().toByteArray(StandardCharsets.UTF_8))
            val request = url!!.openConnection() as HttpURLConnection
            request.requestMethod = "POST"
            request.setRequestProperty("Content-Type", "application/x-www-form-urlencoded")
            request.setRequestProperty("Content-Length", encodedBody.length.toString())
            request.setRequestProperty("Connection", "Keep-Alive")
            request.setRequestProperty("X-Requested-With", "XMLHttpRequest")
            request.doOutput = true
            request.connectTimeout = manager.options.timeout
            request.readTimeout = manager.options.timeout
            val writer = OutputStreamWriter(request.outputStream, StandardCharsets.UTF_8)
            writer.write(encodedBody)
            writer.flush()
            writer.close()
            request.disconnect()
        } catch (e: Exception) {
            Log.e(TAG, "send: $e")
            manager.onClose(e)
        }
    }

    override fun write(data: String) {
        if (!isConnected()) return
        try {
            val request = url!!.openConnection() as HttpURLConnection
            request.requestMethod = "POST"
            request.setRequestProperty("Content-Type", "application/json; charset=UTF-8")
            request.setRequestProperty("Content-Length", data.length.toString())
            request.setRequestProperty("Connection", "Keep-Alive")
            request.setRequestProperty("X-Requested-With", "XMLHttpRequest")
            request.doOutput = true
            request.connectTimeout = manager.options.timeout
            request.readTimeout = manager.options.timeout
            val writer = OutputStreamWriter(request.outputStream, StandardCharsets.UTF_8)
            writer.write(data)
            writer.flush()
            writer.close()
            request.disconnect()
        } catch (e: Exception) {
            Log.e(TAG, "write: $e")
            manager.onClose(e)
        }
    }

    override fun poll() {
        if (!isConnected()) return
        try {
            httpConn = url!!.openConnection() as HttpURLConnection
            httpConn!!.readTimeout = manager.options.timeout
            httpConn!!.connectTimeout = manager.options.timeout
            httpConn!!.requestMethod = "GET"
            httpConn!!.useCaches = false
            httpConn!!.doInput = true
            httpConn!!.connect()
            val reader = BufferedReader(InputStreamReader(httpConn!!.inputStream))
            val response = StringBuilder()
            var line: String?
            while (reader.readLine().also { line = it } != null) {
                response.append(line)
            }
            reader.close()
            httpConn!!.disconnect()
            val messages = parser!!.parse(response.toString())
            for (message in messages) {
                when (message.type) {
                    SocketIOClient.Message.Type.MESSAGE -> {
                        manager.onMessage(message.data)
                    }
                    SocketIOClient.Message.Type.ERROR -> {
                        manager.onError(message.data)
                    }
                    SocketIOClient.Message.Type.CONNECT -> {
                        manager.onOpen()
                    }
                    SocketIOClient.Message.Type.DISCONNECT -> {
                        manager.onClose(IOException("disconnected"))
                    }
                    SocketIOClient.Message.Type.PONG -> {
                        manager.onPong()
                    }
                    else -> throw IllegalArgumentException("unknown message type")
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "poll: $e")
            manager.onClose(e)
        }
    }

    override fun isConnected(): Boolean {
        return parser != null && httpConn != null
    }

    companion object {
        private const val TAG = "HttpPollingTransport"
    }
}

