class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        from collections import Counter
        ans = []
        if len(p) > len(s):
            return ans

        dic = Counter(p)
        temp = Counter(s[:len(p)])
        if temp == dic:
            ans.append(0)

        for i in range(len(p), len(s)):
            temp[s[i]] += 1
            temp[s[i - len(p)]] -= 1
            if temp[s[i - len(p)]] == 0:
                del temp[s[i - len(p)]]
            if temp == dic:
                ans.append(i - len(p) + 1)

        return ans
