import threading
import time
from queue import Queue

class Producer(threading.Thread):

    def __init__(self, t_name, queue):
        super().__init__(name = t_name)
        self.data = queue

    def run(self):
        for i in range(10):
            print('生产者 %s 生产了 %d 个产品放入队列' % (self.getName(), i))
            self.data.put(i)
            time.sleep(1)
            print('当前队列长度为: %d' % self.data.qsize())

class Consumer(threading.Thread):

    def __init__(self, t_name, queue):
        super().__init__(name = t_name)
        self.data = queue

    def run(self):
        while True:
            if self.data.empty():
                break
            else:
                val = self.data.get()
                print('消费者 %s 消耗了 %d 个产品' % (self.getName(), val))
                time.sleep(1)

def main():
    queue = Queue()
    p = Producer('Producer', queue)
    c = Consumer('Consumer', queue)
    p.start()
    c.start()
    p.join()
    c.join()

