        // Custom plain text rendering logic here
        // You can set the font, color, and other styling properties as needed
        run.setText(text);
        run.setFontFamily("Arial");
        run.setFontSize(12);
        run.setBold(true);
        run.setColor(Color.BLUE);
    }
}
