fn min_operations(nums: Vec<i32>) -> i32 {
    let mut operations = 0;
    let n = nums.len();

    for i in 0..(n - 1) {
        if nums[i] < nums[i + 1] {
            operations += nums[i + 1] - nums[i];
        } else {
            operations += nums[i] - nums[i + 1] + 1;
        }
    }

    operations
}

fn main() {
    let nums = vec![1, 4, 3];
    println!("Minimum operations: {}", min_operations(nums));
}
