class Solution {
public:
    bool canMakePaliQueries(string s, vector<vector<int>>& queries) {
        int n = s.size();
        vector<int> freq(n + 1);
        for (int i = 0; i < n; ++i) {
            freq[i + 1] = freq[i] ^ (1 << (s[i] - \'a\'));
        }

        for (const auto& q : queries) {
            int l = q[0], r = q[1], k = q[2];
            int mask = freq[r + 1] ^ freq[l];
            if (__builtin_popcount(mask) / 2 > k)
                return false;
        }
        return true;
    }
};
