/// Finds the integer in the given vector that occurs an odd number of times.
/// Returns -1 if no such integer exists.
///
/// # Examples
/// ```
/// assert_eq!(find_odd_occurrence(vec![20, 1, 1, 2, 2]), 20);
/// assert_eq!(find_odd_occurrence(vec![5, 7, 5, 7, 7]), 7);
/// assert_eq!(find_odd_occurrence(vec![10, 10, 10]), 10);
/// assert_eq!(find_odd_occurrence(vec![1, 2, 3, 4, 5]), -1);
