fn find_odd_occurrence(numbers: Vec<i32>) -> i32 {
    let mut occurrences = HashMap::new();
    for &number in &numbers {
        *occurrences.entry(number).or_insert(0) += 1;
    }
    for (&number, &count) in occurrences.iter() {
        if count % 2 != 0 {
            return number;
        }
    }
    -1
}

