    assert_eq!(find_odd_occurrence(vec![5, 7, 5, 7, 7]), 7);
    assert_eq!(find_odd_occurrence(vec![10, 10, 10]), 10);
    assert_eq!(find_odd_occurrence(vec![1, 2, 3, 4, 5]), -1);
    println!("All tests passed successfully.");
