public class Problem {

    /**
     * Sorts an array of integers in ascending order using the insertion sort algorithm.
     *
     * The method iterates over the array, and for each element, it finds the correct
     * position within the sorted portion of the array by shifting elements. Once the correct
     * position is found, the element is inserted.
     *
     * @param array An array of integers to be sorted.
     */
    public static void performInsertionSort(int[] array) {
        for (int i = 1; i < array.length; i++) {
            int currentValue = array[i];
            int j = i - 1;
            // Shift elements of the sorted segment forward if they are larger than currentValue
            while (j >= 0 && array[j] > currentValue) {
                array[j + 1] = array[j];
                j--;
            }
            // Insert the value at the correct position
            array[j + 1] = currentValue;
        }
    }

    public static void main(String[] args) {
        int[] arr = {22, 11, 99, 88, 9, 7, 42};
        performInsertionSort(arr);
        System.out.println(Arrays.toString(arr));  // Output should be [7, 9, 11, 22, 42, 88, 99]
    }
}

