    function parseUrl(url) {
        const pattern = /^(?:([a-z]+):\/\/)?([^\/]+)(.*)/;
        const match = url.match(pattern);
        if (!match) {
            throw new Error(`Invalid URL: ${url}`);
        }
        return {
            protocol: match[1],
            host: match[2],
            path: match[3]
        };
    }

    // Check if the URL is a valid absolute URL
    try {
        const parts = parseUrl(url);
        if (parts.protocol && parts.host) {
            return true;
        }
    } catch (e) {
        // If parsing fails, it's not a valid URL
    }

    // Check if the URL starts with a supported scheme
    const supportedSchemes = ['http', 'https', 'ftp', 'ftps'];
    const scheme = url.split(':')[0];
    if (supportedSchemes.includes(scheme.toLowerCase())) {
        return true;
    }

    return false;
}

