class Solution {
    public int longestPalindrome(String s) {
        Map<Character, Integer> charCount = new HashMap<>();
        for (char c : s.toCharArray()) {
            charCount.put(c, charCount.getOrDefault(c, 0) + 1);
        }

        int maxLength = 0;
        boolean hasOdd = false;

        for (int count : charCount.values()) {
            if (count % 2 == 0) {
                maxLength += count;
            } else {
                maxLength += count - 1;
                hasOdd = true;
            }
        }

        if (hasOdd) {
            maxLength++;
        }

        return maxLength;
    }
}
