nd::array nd::fft::ifft(const nd::array& data)
{
    if (data.type().code() != ND_FLOAT32 && data.type().code() != ND_COMPLEX64)
        throw std::runtime_error("FFT only supports float and complex types");

    int rank = data.rank();
    int n = 1;
    for (int i = 0; i < rank; i++)
        n *= data.shape(i);

    return _ifft(data, n);
}

