        self._size = 0

    def __len__(self):
        return self._size

    def is_empty(self):
        return self._size == 0

    def prepend(self, elem):
        self._head = self.Node(elem, self._head)
        self._size += 1

    def pop(self):
        if self.is_empty():
            raise LinkedListUnderflow("in LList.pop")
