        self._head = self._head.next
        self._size -= 1
        return e

    def append(self, elem):
        if self.is_empty():
            self._head = self.Node(elem)
        else:
            p = self._head
            while p.next:
                p = p.next
            p.next = self.Node(elem)
        self._size += 1

    def pop_last(self):
        if self.is_empty():
            raise LinkedListUnderflow("in LList.pop_last")
        p = self._head
        if p.next is None:
            e = p.elem
            self._head = None
            self._size -= 1
            return e
