        p = self._head
        while p and not pred(p.elem):
            p = p.next
        return p

    def filter(self, pred):
        p = self._head
        while p:
            if pred(p.elem):
                yield p.elem
            p = p.next

    def elements(self):
        p = self._head
        while p:
            yield p.elem
            p = p.next

    def reverse(self):
        p = None
        while self._head:
            q = self._head
            self._head = q.next
            q.next = p
            p = q
        self._head = p

