def create_recipe(title, instructions, ingredients):
    existing_recipe = Recipe.query.filter_by(title=title).first()
    if existing_recipe:
        return False

    new_recipe = Recipe(title=title, instructions=instructions)
    db.session.add(new_recipe)
    db.session.flush()  # Flush to get the newly created recipe's ID

    for ingredient_data in ingredients:
        ingredient_id = ingredient_data["id"]
        quantity = ingredient_data["quantity"]

        # Check if the ingredient exists
        ingredient = Ingredient.query.get(ingredient_id)
        if not ingredient:
            return False

        # Create a new RecipeIngredient entry
        recipe_ingredient = RecipeIngredient(
            recipe_id=new_recipe.id, ingredient_id=ingredient_id, quantity=quantity
        )
        db.session.add(recipe_ingredient)

    db.session.commit()
    return True


def update_recipe(recipe_id, title=None, instructions=None, ingredients=None):
    recipe = Recipe.query.get(recipe_id)
    if not recipe:
        return False

    if title is not None:
        recipe.title = title
    if instructions is not None:
        recipe.instructions = instructions

    # Update or add new RecipeIngredient entries
    if ingredients is not None:
        current_ingredients = set(recipe.ingredients)
        for ingredient_data in ingredients:
            ingredient_id = ingredient_data["id"]
            quantity = ingredient_data["quantity"]

            # Check if the ingredient exists
            ingredient = Ingredient.query.get(ingredient_id)
            if not ingredient:
                return False

            recipe_ingredient = RecipeIngredient.query.filter_by(
                recipe_id=recipe_id, ingredient_id=ingredient_id
            ).first()

            if recipe_ingredient:
                recipe_ingredient.quantity = quantity
                current_ingredients.remove(ingredient)
            else:
                new_recipe_ingredient = RecipeIngredient(
                    recipe_id=recipe_id, ingredient_id=ingredient_id, quantity=quantity
                )
                db.session.add(new_recipe_ingredient)

        # Delete removed ingredients
        for ingredient in current_ingredients:
            recipe_ingredient = RecipeIngredient.query.filter_by(
                recipe_id=recipe_id, ingredient_id=ingredient.id
            ).first()
            db.session.delete(recipe_ingredient)

    db.session.commit()
    return True


