#include <vector>
#include <algorithm>
using namespace std;

int calculateCost(vector<int>& nums, vector<int>& cost, int target) {
    int result = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        result += abs(nums[i] - target) * cost[i];
    }
    return result;
}

int minCost(vector<int>& nums, vector<int>& cost) {
    int left = *min_element(nums.begin(), nums.end());
    int right = *max_element(nums.begin(), nums.end());

    while (left < right) {
        int mid = (left + right) / 2;
        int costMid = calculateCost(nums, cost, mid);
        int costRight = calculateCost(nums, cost, mid + 1);

        if (costMid < costRight) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return calculateCost(nums, cost, left);
}
