class Solution {
public:
    int longestPalindrome(vector<int>& arr) {
        unordered_map<char,int> mp;
        for(auto it : arr){
            mp[it]++;
        }
        int ans = 0;
        bool odd = false;
        for(auto it : mp){
            if(it.second%2 == 0)
                ans += it.second;
            else{
                odd = true;
                ans += (it.second - 1);
            }
        }
        return odd ? ans + 1 : ans;
    }
};
