import java.util.Arrays;

public class Problem {

    /**
     * Given a sorted array `sortedArray` and a number `targetNumber`, this method finds the closest value to `targetNumber` in `sortedArray`.
     * It returns an array containing the index of the closest value and the closest value itself.
     *
     * If `targetNumber` is exactly in `sortedArray`, it returns the index and value of `targetNumber`.
     * If `targetNumber` is between two values, it returns the one that is closer.
     * If the two surrounding values are equally close, the smaller one is considered closer.
     *
     * Parameters:
     * - targetNumber: The number to find the closest value to.
     * - sortedArray: A sorted array of numbers.
     *
     * Returns:
     * - An array [index, value] where `index` is the position in `sortedArray` where the closest value is found,
     *   and `value` is the closest value itself.
     */
    public static int[] findClosestValue(int targetNumber, int[] sortedArray) {
        if (sortedArray == null || sortedArray.length == 0) {
            throw new IllegalArgumentException("The array must not be empty.");
        }

        int pos = Arrays.binarySearch(sortedArray, targetNumber);
        if (pos >= 0) {
            return new int[]{pos, sortedArray[pos]};
        }

        int insertPoint = -(pos + 1);
        if (insertPoint == 0) {
            return new int[]{0, sortedArray[0]};
        }
        if (insertPoint == sortedArray.length) {
            return new int[]{sortedArray.length - 1, sortedArray[sortedArray.length - 1]};
        }

        int beforeIndex = insertPoint - 1;
        int afterIndex = insertPoint;
        int beforeValue = sortedArray[beforeIndex];
        int afterValue = sortedArray[afterIndex];

        if ((targetNumber - beforeValue) <= (afterValue - targetNumber)) {
            return new int[]{beforeIndex, beforeValue};
        } else {
            return new int[]{afterIndex, afterValue};
        }
    }

    // Main function to test the generated function
    public static void main(String[] args) {
        int[] exampleArray = {1, 4, 6, 8};
        System.out.println(Arrays.toString(findClosestValue(5, exampleArray))); // Output: [1, 4]
        System.out.println(Arrays.toString(findClosestValue(7, exampleArray))); // Output: [2, 6]
        System.out.println(Arrays.toString(findClosestValue(3, exampleArray))); // Output: [0, 1]
    }
}

